from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cnt=Counter(x for r in g for x in r if x!=bg)
    # rectangle color: color with largest component
    comps={}
    def largest_comp_size(c):
        seen=set(); best=0
        for i in range(H):
            for j in range(W):
                if g[i][j]==c and (i,j) not in seen:
                    st=[(i,j)]; seen.add((i,j)); n=0
                    while st:
                        a,b=st.pop(); n+=1
                        for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==c and (x,y) not in seen:
                                seen.add((x,y)); st.append((x,y))
                    best=max(best,n)
        return best
    C=max(cnt, key=lambda c: largest_comp_size(c))
    # components of C with size>=2: fill bbox
    out=[r[:] for r in g]
    seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==C and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==C and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                if len(cells)>=2:
                    rs=[a for a,b in cells]; cs=[b for a,b in cells]
                    for r in range(min(rs),max(rs)+1):
                        for c2 in range(min(cs),max(cs)+1):
                            out[r][c2]=C
    for i in range(H):
        for j in range(W):
            if out[i][j]!=C and out[i][j]!=bg:
                out[i][j]=bg
    return out
