def transform(g, thresh=3):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    comps=[]; seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                c=g[i][j]; st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==c and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                comps.append((len(cells),c,cells))
    out=[[bg]*W for _ in range(H)]
    for n,c,cells in sorted(comps, reverse=True):
        if n>=thresh:
            rs=[a for a,b in cells]; cs=[b for a,b in cells]
            for r2 in range(min(rs),max(rs)+1):
                for c2 in range(min(cs),max(cs)+1):
                    out[r2][c2]=c
    return out
